// Device-local media storage. Exported backups include these blobs.
let database;
function db(){if(!database)database=new Promise((resolve,reject)=>{const request=indexedDB.open('motion-atlas-media',1);request.onupgradeneeded=()=>{const store=request.result.createObjectStore('files',{keyPath:'id'});store.createIndex('entryId','entryId',{unique:false})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return database}
async function transaction(mode,action){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('files',mode);let result;try{result=action(tx.objectStore('files'))}catch(error){reject(error);return}tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Media storage was interrupted.'))})}
export async function listFiles(entryId){const database=await db();return new Promise((resolve,reject)=>{const store=database.transaction('files').objectStore('files');const request=entryId?store.index('entryId').getAll(entryId):store.getAll();request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
export async function uploadFiles(entryId,files,role){for(const file of files)if(file.size>100*1024*1024)throw Error('Each file must be 100 MB or smaller. Use a reference link for larger videos.');const records=files.map(file=>({id:crypto.randomUUID(),entryId,name:file.name,type:file.type||'application/octet-stream',size:file.size,role,addedAt:new Date().toISOString(),blob:file}));await transaction('readwrite',store=>records.forEach(file=>store.put(file)));return records}
export async function removeFile(id){await transaction('readwrite',store=>store.delete(id))}
function encode(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.slice(reader.result.indexOf(',')+1));reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
export async function exportFiles(){const records=await listFiles();const result=[];for(const {blob,...meta} of records)result.push({...meta,base64:await encode(blob)});return result}
export function decodeFiles(records,known){if(!Array.isArray(records))throw Error('Invalid media backup.');return records.map(file=>{if(!file||typeof file.id!=='string'||!known.has(file.entryId)||typeof file.name!=='string'||typeof file.base64!=='string'||file.base64.length>140*1024*1024)throw Error('Invalid media file in backup.');const raw=atob(file.base64),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const {base64,...meta}=file;return {...meta,size:bytes.length,blob:new Blob([bytes],{type:file.type||'application/octet-stream'})}})}
export async function restoreFiles(records){await transaction('readwrite',store=>records.forEach(file=>store.put(file)))}
